{
  "bioavailability_prediction": "high",
  "claims": [
    {
      "card_ids": ["C47"],
      "claim": "Levofloxacin absolute oral bioavailability was approximately 99% in healthy volunteers after a 500 mg oral dose, strongly supporting F >= 20%.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C51"],
      "claim": "Trovafloxacin mean absolute oral bioavailability was 87.6% in 12 fasting healthy volunteers after a 200 mg oral tablet dose compared with intravenous alatrofloxacin, supporting high bioavailability.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C37"],
      "claim": "Cilomilast mean absolute oral bioavailability was 96% (range 92-102%) in healthy male volunteers after a 10 mg oral solution compared with intravenous infusion, supporting high bioavailability.",
      "evidence_role": "supportive"
    }
  ],
  "confidence": "high",
  "decision_summary": "All supplied evidence molecules show oral bioavailability values above the 20% threshold; absolute human measurements range from about 32% for encainide to 87-100% for several other compounds, so high F is supported.",
  "evidence_gaps": [
    "Some records are qualitative ('high', 'good') rather than numeric absolute bioavailability, but quantitative absolute measurements corroborate high F.",
    "Encainide shows a wide interindividual bioavailability range in one record (7-82%), although mean values remain above 20%."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

